import { supabase } from './supabase';

/**
 * Find a consequence by its consequence_id.
 */
async function findConsequence(consequence_id) {
  if (!consequence_id) {
    throw new Error('consequence_id is required');
  }

  console.log('Finding consequence:', consequence_id);

  try {
    const { data, error } = await supabase
      .from('hira_consequences')
      .select(`
        id,
        description,
        current_controls,
        hazard:hira_hazards!inner(
          id,
          description,
          event:hira_events!inner(
            id,
            name
          )
        )
      `)
      .eq('id', consequence_id)
      .maybeSingle();

    if (error) {
      console.error('Database error finding consequence:', error);
      throw error;
    }

    if (!data) {
      console.error('Consequence not found:', consequence_id);
      throw new Error(`Consequence with ID ${consequence_id} not found in database`);
    }

    console.log('Found consequence:', data);
    return data;
  } catch (error) {
    console.error('Error in findConsequence:', error);
    throw error;
  }
}

/**
 * Create or update a single risk assessment.
 */
async function createOrUpdateAssessment(assessment, matrix_type) {
  let result;
  let consequence;

  try {
    // First verify the consequence exists and get its full data
    consequence = await findConsequence(assessment.consequence_id);
    if (!consequence) {
      throw new Error(`Cannot create/update assessment: Consequence ${assessment.consequence_id} not found`);
    }

    // Check if an assessment already exists for this consequence
    const { data: existingAssessment, error: fetchError } = await supabase
      .from('hira_risk_assessments')
      .select('id, consequence_id')
      .eq('consequence_id', consequence.id)
      .maybeSingle();

    if (fetchError) {
      console.error('Error checking existing assessment:', fetchError);
      throw fetchError;
    }

    // Prepare assessment data
    const assessmentData = {
      consequence_id: consequence.id,  // Always use the consequence's actual ID
      matrix_type: matrix_type.toLowerCase(),
      probability: assessment.probability ? parseInt(assessment.probability) : null,
      severity: assessment.severity || null,
      likelihood: assessment.likelihood ? parseInt(assessment.likelihood) : null,
      impact: assessment.impact ? parseInt(assessment.impact) : null,
      tolerability: assessment.tolerability || null,
      updated_at: new Date().toISOString()
    };

    if (existingAssessment) {
      const { data, error } = await supabase
        .from('hira_risk_assessments')
        .update(assessmentData)
        .eq('id', existingAssessment.id)
        .select()
        .single();

      if (error) throw error;
      result = data;
    } else {
      const { data, error } = await supabase
        .from('hira_risk_assessments')
        .insert({
          ...assessmentData,
          created_at: new Date().toISOString()
        })
        .select()
        .single();

      if (error) throw error;
      result = data;
    }

    return {
      assessment_id: result.id,
      consequence_id: consequence.id,
      event: consequence.hazard.event.name,
      hazard: consequence.hazard.description,
      consequence: consequence.description,
      current_controls: consequence.current_controls,
      matrix_type: result.matrix_type,
      probability: result.probability,
      severity: result.severity,
      likelihood: result.likelihood,
      impact: result.impact,
      tolerability: result.tolerability
    };
  } catch (error) {
    console.error('Error in createOrUpdateAssessment:', error);
    throw error;
  }
}

/**
 * Create multiple risk assessments.
 */
export async function createAssessments(project_id, assessmentsData, matrix_type) {
  try {
    // Validate all assessments have consequence IDs before processing
    const invalidAssessments = assessmentsData.assessments.filter(
      assessment => !assessment.consequence_id
    );

    if (invalidAssessments.length > 0) {
      const errorDetails = invalidAssessments.map(assessment => ({
        event: assessment.event,
        hazard: assessment.hazard,
        consequence: assessment.consequence
      }));

      throw new Error(
        `Cannot create risk assessments: Missing consequence IDs\n` +
        `This usually indicates that the consequences were not properly saved in the database.\n` +
        `Affected items: ${JSON.stringify(errorDetails, null, 2)}`
      );
    }

    // Verify consequences exist in database before creating assessments
    const verificationPromises = assessmentsData.assessments.map(async assessment => {
      const consequence = await findConsequence(assessment.consequence_id);
      if (!consequence) {
        throw new Error(
          `Consequence with ID ${assessment.consequence_id} not found in database.\n` +
          `Event: ${assessment.event}\nHazard: ${assessment.hazard}`
        );
      }
      return consequence;
    });

    await Promise.all(verificationPromises);

    // Proceed with creating assessments
    const assessmentPromises = assessmentsData.assessments.map(async assessment => {
      return createOrUpdateAssessment(assessment, matrix_type);
    });

    const results = await Promise.all(assessmentPromises);
    return { assessments: results };
  } catch (error) {
    console.error('Error creating assessments:', error);
    throw error;
  }
}

/**
 * Update multiple risk assessments.
 */
export async function updateAssessments(assessmentsData, matrix_type) {
  const updatePromises = assessmentsData.assessments.map(async assessment => {
    return createOrUpdateAssessment(assessment, matrix_type);
  });

  try {
    const results = await Promise.all(updatePromises);
    return { assessments: results };
  } catch (error) {
    console.error('Error updating assessments:', error);
    throw error;
  }
}

/**
 * Get an assessment by consequence_id.
 */
export async function getAssessmentsByConsequenceId(consequence_id) {
  if (!consequence_id) {
    console.error('getAssessmentsByConsequenceId called without consequence_id');
    return null;
  }

  try {
    // First verify the consequence exists
    const consequence = await findConsequence(consequence_id);
    if (!consequence) {
      console.log('No consequence found for ID:', consequence_id);
      return null;
    }

    // Then get the assessment
    const { data: assessment, error } = await supabase
      .from('hira_risk_assessments')
      .select()
      .eq('consequence_id', consequence.id)
      .maybeSingle();

    if (error) {
      console.error('Error fetching assessment:', error);
      throw error;
    }

    if (!assessment) {
      console.log('No assessment found for consequence:', consequence_id);
      return null;
    }

    return {
      assessment_id: assessment.id,
      consequence_id: consequence.id,
      event: consequence.hazard.event.name,
      hazard: consequence.hazard.description,
      consequence: consequence.description,
      current_controls: consequence.current_controls,
      matrix_type: assessment.matrix_type,
      probability: assessment.probability,
      severity: assessment.severity,
      likelihood: assessment.likelihood,
      impact: assessment.impact,
      tolerability: assessment.tolerability
    };
  } catch (error) {
    console.error('Error getting assessment:', error);
    throw error;
  }
}
